contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 v, address target, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v);

        uint256 testBalBefore = address(this).balance;

        bool reverted;
        c.Command{value: v}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 testBalAfter = address(this).balance;

        assert(!reverted || testBalAfter == testBalBefore - v);
    }
}

